import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Tenant Settings — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant Settings — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/tenant-settings"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant Settings — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/tenant-settings"}]]},"headers":[],"relativePath":"user-guide/tenant-settings.md","filePath":"user-guide/tenant-settings.md","lastUpdated":1787354383000}'),r={name:"user-guide/tenant-settings.md"};function s(i,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="tenant-settings-—-user-guide" tabindex="-1">Tenant Settings — User Guide <a class="header-anchor" href="#tenant-settings-—-user-guide" aria-label="Permalink to &quot;Tenant Settings — User Guide&quot;">​</a></h1><p>Workspace <strong>Settings</strong> lets each tenant customize identity and mail without affecting other workspaces or the Central Application.</p><h2 id="open-settings" tabindex="-1">Open Settings <a class="header-anchor" href="#open-settings" aria-label="Permalink to &quot;Open Settings&quot;">​</a></h2><p>In the Tenant Application sidebar, open <strong>Settings</strong>.</p><p>You need permission to view/update settings (workspace owners have this by default).</p><h2 id="workspace-timezone" tabindex="-1">Workspace timezone <a class="header-anchor" href="#workspace-timezone" aria-label="Permalink to &quot;Workspace timezone&quot;">​</a></h2><p><strong>Timezone</strong> under General is the single clock for the whole workspace. When it is set to e.g. <code>Asia/Karachi</code>, every date and time in the Tenant Application follows that zone — not the server’s UTC clock and not the browser’s local zone alone:</p><ul><li>Daily Reminder Time (task digest + daily CRM summary emails)</li><li>Task due dates and lead follow-up due times</li><li>Meeting and calendar start/end times (and meeting reminders)</li><li>Attendance “today”, login check-in time, and office start/end + late grace</li></ul><p>There is no separate attendance or meeting timezone. Change <strong>Timezone</strong> once; all of the above move with it. The same rule applies to every current module and any future module that shows dates, due times, schedules, or office hours.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Workspace Name</strong></td><td>Display name for the workspace. Also used as the browser/app title unless you set Application Name.</td></tr><tr><td><strong>Application Name</strong></td><td>Optional title override. Leave blank to use Workspace Name.</td></tr><tr><td><strong>Company Name</strong></td><td>Used in emails and documents.</td></tr><tr><td><strong>Timezone</strong></td><td>Workspace wall-clock zone for reminders, due dates, meetings, calendar, and attendance. Inherit from Central when not customized.</td></tr><tr><td><strong>Locale / Currency</strong></td><td>Workspace defaults. Inherit from Central when not customized.</td></tr><tr><td><strong>Daily Reminder Time</strong></td><td>Local workspace time (default <code>09:00</code>) in <strong>Timezone</strong> — not server UTC — for the daily CRM summary email and the consolidated task due digest. Assignees still get in-app alerts per due/overdue task.</td></tr><tr><td><strong>Default meeting provider</strong></td><td>Preselects None / Google Meet / Zoom on the Meetings schedule form (<code>meetings_default_provider</code>). Connecting providers is done under Meetings → Integrations.</td></tr><tr><td><strong>Trash retention</strong></td><td>How long soft-deleted items stay in Trash before automatic permanent purge (<code>trash.retention_days</code>). Choose <strong>30</strong>, <strong>90</strong>, or <strong>365</strong> days, or <strong>Forever</strong>. Applies to leads, tasks, contacts, companies, invoices, and other SoftDeletes modules (not Team Chat messages — see Team Chat retention; not Email mailboxes — disconnect those separately; not IMAP Email Trash folders). Purge is irreversible.</td></tr></tbody></table><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p><strong>Settings → Notifications</strong> controls which <strong>event emails</strong> the workspace sends. Defaults are <strong>off</strong> for every toggle. In-app notifications and browser push are not affected.</p><table tabindex="0"><thead><tr><th>Toggle</th><th>When email is sent (if enabled)</th></tr></thead><tbody><tr><td><strong>Task assigned</strong></td><td>A task is assigned to someone</td></tr><tr><td><strong>Task completed / reopened</strong></td><td>A task is completed or reopened</td></tr><tr><td><strong>Mentioned in a task comment</strong></td><td>Someone @mentions you in a task comment</td></tr><tr><td><strong>Follow-up created</strong></td><td>A lead follow-up is created</td></tr><tr><td><strong>Follow-up due / overdue</strong></td><td>A lead follow-up becomes due or overdue</td></tr><tr><td><strong>Mentioned in a lead note</strong></td><td>Someone @mentions you in a lead note</td></tr><tr><td><strong>Meeting events</strong></td><td>Meeting invite, update, cancel, or reminder</td></tr><tr><td><strong>Other module assignments</strong></td><td>Contact, company, opportunity, invoice, and similar assignment emails</td></tr></tbody></table><p>Always sent (not toggleable here):</p><ul><li>Daily task due digest and daily CRM summary (at <strong>Daily Reminder Time</strong>)</li><li>Auth emails (password reset, email verification)</li></ul><h2 id="team-chat" tabindex="-1">Team Chat <a class="header-anchor" href="#team-chat" aria-label="Permalink to &quot;Team Chat&quot;">​</a></h2><p>Shown when the <strong>Team Chat</strong> module is installed.</p><table tabindex="0"><thead><tr><th>Field</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Message &amp; file retention</strong></td><td>How long Team Chat keeps messages and attachments (<code>team-chat.retention_days</code>). Choose <strong>30</strong>, <strong>90</strong>, or <strong>365</strong> days, or <strong>Forever</strong>. Forever keeps history indefinitely; otherwise older messages (and their files) are permanently purged on a schedule.</td></tr></tbody></table><p>See <a href="/user-guide/team-chat">Team Chat</a>.</p><h2 id="attendance" tabindex="-1">Attendance <a class="header-anchor" href="#attendance" aria-label="Permalink to &quot;Attendance&quot;">​</a></h2><p>Shown when the <strong>Attendance</strong> module is installed.</p><table tabindex="0"><thead><tr><th>Field</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Office start / end time</strong></td><td>Local workspace office hours (<strong>Timezone</strong> above) used for login check-in classification. Separate from Daily Reminder Time.</td></tr><tr><td><strong>Grace period (minutes)</strong></td><td>Check-ins after start time plus grace are marked <strong>Late</strong> (default <code>15</code>).</td></tr><tr><td><strong>Work week days</strong></td><td>Weekdays that count as working days for payroll calendars (default Mon–Fri), using workspace-local dates.</td></tr></tbody></table><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Session timeout (minutes)</strong></td><td>How long a signed-in user may stay idle before the app signs them out. Inherits the Central platform default when not customized.</td></tr><tr><td><strong>Never timeout</strong></td><td>Sets timeout to <code>0</code> so users stay signed in until they use <strong>Sign out</strong> (or an admin revokes their token). Issues a non-expiring API token for that workspace.</td></tr></tbody></table><p>Password length / special-character rules stay under Central Settings.</p><h2 id="branding" tabindex="-1">Branding <a class="header-anchor" href="#branding" aria-label="Permalink to &quot;Branding&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Button color</strong></td><td>Primary buttons, accents, and invoice PDF chrome for this workspace.</td></tr><tr><td><strong>Support email</strong></td><td>Shown in tenant-facing emails and on invoice PDFs when set.</td></tr><tr><td><strong>Logo / Favicon</strong></td><td>Upload immediately. Logo is embedded on invoice PDFs. If unset, the app falls back to Central branding when uploaded, otherwise the EloSync press-kit App Store light icon. Invoice PDFs omit the logo until you upload one.</td></tr></tbody></table><h3 id="invoice-company-profile" tabindex="-1">Invoice company profile <a class="header-anchor" href="#invoice-company-profile" aria-label="Permalink to &quot;Invoice company profile&quot;">​</a></h3><p>Used on customer invoice PDFs (header and footer):</p><table tabindex="0"><thead><tr><th>Field</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Tagline</strong></td><td>Short line under the company name</td></tr><tr><td><strong>Address / Phone / Website</strong></td><td>Contact block</td></tr><tr><td><strong>Default payment terms</strong></td><td>e.g. Net 15 Days — used when issue/due dates cannot derive Net X days</td></tr><tr><td><strong>Default invoice notes</strong></td><td>Printed when the invoice memo is empty</td></tr></tbody></table><h3 id="invoice-payment-details" tabindex="-1">Invoice payment details <a class="header-anchor" href="#invoice-payment-details" aria-label="Permalink to &quot;Invoice payment details&quot;">​</a></h3><p>Bank name, account name/number, IBAN, and SWIFT/BIC. If any field is set, the PDF shows a <strong>Payment Information</strong> section; leave all blank to hide it.</p><p>Hints under fields show when a value is still inheriting the Central default (branding color/email) or is unset.</p><p>With the <strong>Branded</strong> marketplace module, logo and application name are also used in email chrome and web push. See <a href="/user-guide/branded">Branded</a>.</p><h2 id="marketplace" tabindex="-1">Marketplace <a class="header-anchor" href="#marketplace" aria-label="Permalink to &quot;Marketplace&quot;">​</a></h2><p>When Marketplace is enabled for the platform, <strong>Settings → Marketplace</strong> links to the catalog. From there you can <strong>Install</strong> free modules, <strong>Subscribe</strong> to paid ones, and <strong>Remove</strong> / <strong>Cancel subscription</strong> for opt-in modules you no longer need. Core modules (Leads, Tasks) cannot be removed. See <a href="/user-guide/tenant-application#marketplace-add--remove-modules">Tenant Application</a>.</p><h2 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h2><p>When <strong>Storage</strong> is installed, <strong>Settings → Storage</strong> shows used / allowance bytes, the current pack (or Free 1 GB), and a link to upgrade in Marketplace. See <a href="/user-guide/storage">Storage</a>.</p><h2 id="domain-branded-module" tabindex="-1">Domain (Branded module) <a class="header-anchor" href="#domain-branded-module" aria-label="Permalink to &quot;Domain (Branded module)&quot;">​</a></h2><p>When <strong>Branded</strong> is installed, <strong>Settings → Domain</strong> walks you through a three-step flow: enter your website address, copy DNS records into your domain provider, then check the connection. See <a href="/user-guide/branded">Branded</a>.</p><h2 id="mail" tabindex="-1">Mail <a class="header-anchor" href="#mail" aria-label="Permalink to &quot;Mail&quot;">​</a></h2><p>Choose <strong>Use system provider</strong> to inherit Central Application mail, or <strong>Use custom provider</strong> for workspace-specific SMTP / Postmark / Mailgun.</p><ul><li>Password and API token fields never show the stored secret; leave blank to keep the existing value.</li><li>With a custom Postmark/Mailgun provider, copy the workspace <strong>Webhook URL</strong>, set the signing secret, and select delivery events to process.</li><li>Use <strong>Send test</strong> to verify delivery (uses the form values, including unsaved changes when supported).</li><li>Delivery history is available under <strong>Email logs</strong> — open a message to view the full body and <strong>Resend</strong> when permitted.</li></ul><h2 id="developers" tabindex="-1">Developers <a class="header-anchor" href="#developers" aria-label="Permalink to &quot;Developers&quot;">​</a></h2><p>Requires permission <code>settings.manage_developers</code> (workspace owners and admins by default).</p><p><strong>Settings → Developers</strong> is the workspace-wide integration surface (not a Marketplace module):</p><table tabindex="0"><thead><tr><th>Section</th><th>What it does</th></tr></thead><tbody><tr><td><strong>API tokens</strong></td><td>Create long-lived Bearer tokens (<code>es_…</code>) for calling <code>/api/tenant/v1</code>. The plaintext secret is shown <strong>once</strong> on create/rotate. Tokens act as the creating user — prefer a dedicated integration user with least privilege.</td></tr><tr><td><strong>Outbound webhooks</strong></td><td>Subscribe to domain events (<code>lead.created</code>, <code>task.completed</code>, …). EloSync POSTs a signed JSON envelope to your HTTPS URL. Signing secret shown once. Use <strong>Send test</strong>, <strong>Enable/Disable</strong>, and review <strong>Recent deliveries</strong>. Rotate/delete ask for confirmation.</td></tr></tbody></table><p>This is separate from <strong>Leads → Integrations</strong> (inbound lead ingest) and Automation’s per-workflow webhook action.</p><p>See <a href="/developer-guide/tenant-api-webhooks">Tenant API &amp; Webhooks</a> and <a href="/api/tenant-v1-developers">Tenant Developers API</a>.</p><h2 id="what-you-cannot-change" tabindex="-1">What you cannot change <a class="header-anchor" href="#what-you-cannot-change" aria-label="Permalink to &quot;What you cannot change&quot;">​</a></h2><p>Platform registration, maintenance mode, password policy, and billing defaults stay under Central Settings.</p>',52)])])}const p=t(r,[["render",s]]);export{m as __pageData,p as default};
